import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G)); print(G['Demo pair 1 input']==G['Demo pair 1 output'] and 'same' or 'diff')

def boxes(g):
    colors=set(v for r in g for v in r)-{0}
    out={}
    for c in colors:
        pts=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v==c]
        rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
        out[c]=(min(rs),min(cs),max(rs),max(cs))
    return out
def find_boxes(g):
    b=boxes(g)
    # frame box: top row all color
    res={}
    for c,(r0,c0,r1,c1) in b.items():
        if all(g[r0][j]==c for j in range(c0,c1+1)) and all(g[i][c0]==c for i in range(r0,r1+1)) and all(g[i][c1]==c for i in range(r0,r1+1)) and all(g[r1][j]==c for j in range(c0,c1+1)):
            res[c]=(r0,c0,r1,c1)
    return res
