import numpy as np
def transforms(a):
    return {'id':a,'h':a[:,::-1],'v':a[::-1],'180':a[::-1,::-1],'t':a.T,'th':a.T[:,::-1],'tv':a.T[::-1],'r90':a.T[::-1,::-1]}
def frames(g):
    res={}
    for c in set(v for r in g for v in r)-{0}:
        pts=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v==c]
        r0,c0=min(p[0] for p in pts),min(p[1] for p in pts); r1,c1=max(p[0] for p in pts),max(p[1] for p in pts)
        if (all(g[r0][j]==c for j in range(c0,c1+1)) and all(g[r1][j]==c for j in range(c0,c1+1))
            and all(g[i][c0]==c for i in range(r0,r1+1)) and all(g[i][c1]==c for i in range(r0,r1+1))):
            res[c]=(r0,c0,r1,c1)
    return res
def f(g):
    g=[row[:] for row in g]; fb=frames(g)
    # source: box with nonzero interior
    src=None
    for c,(r0,c0,r1,c1) in fb.items():
        if any(g[i][j]!=0 for i in range(r0+1,r1) for j in range(c0+1,c1)):
            src=(c,(r0,c0,r1,c1))
    sc,(sr0,sc0,sr1,sc1)=src
    pat=np.array([[g[i][j] for j in range(sc0+1,sc1)] for i in range(sr0+1,sr1)])
    ph,pw=pat.shape
    scy,scx=(sr0+sr1)/2,(sc0+sc1)/2
    for c,(r0,c0,r1,c1) in fb.items():
        if c==sc: continue
        ih,iw=r1-r0-1,c1-c0-1
        cy,cx=(r0+r1)/2,(c0+c1)/2
        dy=1 if cy>scy else (-1 if cy<scy else 0)
        dx=1 if cx>scx else (-1 if cx<scx else 0)
        name={(1,1):'180',(-1,1):'h',(1,-1):'v',(-1,-1):'id'}.get((dy,dx))
        T=transforms(pat)[name] if name else None
        if T is None or T.shape!=(ih,iw):
            # try any transform that fits; else erase
            cand=[n for n,B in transforms(pat).items() if B.shape==(ih,iw)]
            if not cand:
                for i in range(r0,r1+1):
                    for j in range(c0,c1+1): g[i][j]=0
                continue
            T=transforms(pat)[cand[0]]
        for i in range(ih):
            for j in range(iw):
                if T[i,j]: g[r0+1+i][c0+1+j]=c
    return g
